#!/usr/bin/env python3
"""Configure a fresh pi-gen checkout and describe its exported RNBO image."""

import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import shlex
import shutil
import subprocess
import sys
import zipfile


def settings():
    version = os.environ["RNBO_RUNNER_VERSION"]
    if not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+-[0-9]+", version):
        raise ValueError("Runner version must be an exact package version, e.g. 1.4.6-9")
    release, bits = os.environ["IMAGE_RELEASE"], os.environ["IMAGE_BITS"]
    if (release, bits) not in {("trixie", "64"), ("bookworm", "32")}:
        raise ValueError("Expected trixie/64 or bookworm/32")
    name = f"raspios-{release}-lite-{bits}bit-rnbooscquery-{version}"
    return version, release, bits, name


def configure(root):
    version, release, bits, name = settings()
    # Never reuse a rootfs or export from an earlier package repository snapshot.
    for directory in ("work", "deploy"):
        if (root / directory).exists() and any((root / directory).iterdir()):
            raise ValueError(f"Use a fresh checkout: {directory} is not empty")
    config = {
        "RELEASE": release,
        "DEPLOY_COMPRESSION": "zip",
        "ENABLE_SSH": "1",
        "FIRST_USER_NAME": "pi",
        "FIRST_USER_PASS": os.environ.get("FIRST_USER_PASS", "c74rnbo"),
        "DISABLE_FIRST_BOOT_USER_RENAME": "1",
        "TARGET_HOSTNAME": "c74rpi",
        "STAGE_LIST": "stage0 stage1 stage2",
        "RNBO_RUNNER_VERSION": version,
        "IMG_NAME": name,
        "IMG_FILENAME": name,
        "ARCHIVE_FILENAME": name + ".img",
        "IMG_DATE": datetime.datetime.now(datetime.timezone.utc).date().isoformat(),
    }
    (root / "config").write_text(
        "# Generated by the RNBO image workflow.\n"
        + "".join(f"{key}={shlex.quote(value)}\n" for key, value in config.items())
        + "export DEBIAN_FRONTEND=noninteractive\n"
    )
    (root / "config").chmod(0o600)
    # stage2 normally appends -lite after IMG_FILENAME and ARCHIVE_FILENAME.
    # Our public names already include lite in the middle of the name.
    (root / "stage2/EXPORT_IMAGE").write_text('IMG_SUFFIX=""\n')
    verify = root / "stage2/99-rnbo-verify"
    verify.mkdir(exist_ok=True)
    shutil.copyfile(Path(__file__).with_name("verify-image.sh"), verify / "00-run.sh")
    (verify / "00-run.sh").chmod(0o755)
    print(f"Building {name}.img.zip from {subprocess.check_output(['git', '-C', str(root), 'rev-parse', 'HEAD'], text=True).strip()}")


def digest(stream):
    sha = hashlib.sha256()
    size = 0
    while chunk := stream.read(1024 * 1024):
        sha.update(chunk)
        size += len(chunk)
    return size, sha.hexdigest()


def metadata(root):
    version, release, bits, name = settings()
    deploy = root / "deploy"
    archive = deploy / (name + ".img.zip")
    if list(deploy.glob("*.zip")) != [archive]:
        raise ValueError(f"Expected exactly one image archive: {archive.name}")
    with zipfile.ZipFile(archive) as zipped:
        if zipped.namelist() != [name + ".img"]:
            raise ValueError("Archive must contain exactly the expected .img file")
        # Reading through EOF also checks the ZIP member's CRC.
        with zipped.open(name + ".img") as image:
            image_size, image_sha = digest(image)
    if image_size == 0:
        raise ValueError("Image is empty")
    with archive.open("rb") as stream:
        download_size, download_sha = digest(stream)
    # The image's build date, not a potentially different date after midnight.
    date_line = next(line for line in (root / "config").read_text().splitlines()
                     if line.startswith("IMG_DATE="))
    release_date = shlex.split(date_line.split("=", 1)[1])[0]
    entry = {
        "name": f"RNBO {version.rsplit('-', 1)[0]} ({release.title()}, {bits}-bit)",
        "description": f"RNBO customized {release} installation",
        "icon": "https://assets.cycling74.com/rnbo/pi-images/rnbo.png",
        "url": f"https://assets.cycling74.com/rnbo/pi-images/{archive.name}",
        "extract_size": image_size,
        "extract_sha256": image_sha,
        "image_download_size": download_size,
        "release_date": release_date,
        "init_format": "systemd",
        "capabilities": [],
        "devices": [f"pi{model}-{bits}bit" for model in (5, 4, 3)],
    }
    rendered = json.dumps(entry, indent=2) + "\n"
    (deploy / "repo-entry.json").write_text(rendered)
    (deploy / (archive.name + ".sha256")).write_text(f"{download_sha}  {archive.name}\n")
    provenance = {
        "runner_version": version,
        "image_commit": subprocess.check_output(
            ["git", "-C", str(root), "rev-parse", "HEAD"], text=True).strip(),
        "workflow_commit": os.environ.get("GITHUB_SHA"),
        "run_id": os.environ.get("GITHUB_RUN_ID"),
    }
    (deploy / "build-manifest.json").write_text(json.dumps(provenance, indent=2) + "\n")
    if summary := os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(summary, "a") as stream:
            stream.write(f"### {release.title()} {bits}-bit\n\n```json\n{rendered}```\n")
    print(rendered, end="")


if __name__ == "__main__":
    if len(sys.argv) != 3 or sys.argv[1] not in {"configure", "metadata"}:
        sys.exit("Usage: image.py {configure|metadata} PI_GEN_CHECKOUT")
    {"configure": configure, "metadata": metadata}[sys.argv[1]](Path(sys.argv[2]))
